/*
 * Phone launcher PH1 — app list from the Hub catalog, READ ONLY.
 * Source: window.HUB_APP_INDEX (hub/core/hub_appindex.js, generated by hub_appindex_gen.py):
 *   id -> [category, entry (repo-root relative), name, icon, newTab(, description)].
 * Category order: window.HUB_CAT_CSV keys (hub/core/hub_config.js); unknown categories go last.
 * The launcher lives in phone/, so every path gets '../' (absolute http(s) URLs are kept).
 */
(function () {
  'use strict';
  var idx = window.HUB_APP_INDEX || {};
  var order = Object.keys(window.HUB_CAT_CSV || {});
  var abs = function (p) { return /^(https?:)?\/\//i.test(p) ? p : '../' + String(p || '').replace(/^\.?\//, ''); };
  var apps = {};
  Object.keys(idx).forEach(function (id) {
    var r = idx[id];
    if (!Array.isArray(r) || !r[1]) return;
    apps[id] = { id: id, cat: String(r[0] || 'Other'), url: abs(r[1]), name: String(r[2] || id), icon: r[3] ? abs(r[3]) : '', newTab: !!r[4], desc: String(r[5] || '') };
  });
  var cats = [];
  Object.keys(apps).forEach(function (id) { var c = apps[id].cat; if (cats.indexOf(c) < 0) cats.push(c); });
  cats.sort(function (a, b) {
    var ia = order.indexOf(a), ib = order.indexOf(b);
    return (ia < 0 ? 99 : ia) - (ib < 0 ? 99 : ib) || a.localeCompare(b);
  });
  var byName = function (a, b) { return a.name.localeCompare(b.name, undefined, { sensitivity: 'base' }); };
  window.PhoneApps = {
    get: function (id) { return apps[id] || null; },
    has: function (id) { return !!apps[id]; },
    cats: function () { return cats.slice(); },
    /** cat '' or 'All' = every app; alphabetical. */
    list: function (cat) {
      return Object.keys(apps).map(function (k) { return apps[k]; })
        .filter(function (a) { return !cat || cat === 'All' || a.cat === cat; }).sort(byName);
    },
    /** Name first, then category / description matches. */
    search: function (q) {
      q = String(q || '').trim().toLowerCase();
      if (!q) return this.list('');
      var hit = [], soft = [];
      this.list('').forEach(function (a) {
        var n = a.name.toLowerCase();
        if (n.indexOf(q) === 0 || n.indexOf(' ' + q) >= 0) hit.push(a);
        else if (n.indexOf(q) >= 0 || a.cat.toLowerCase().indexOf(q) === 0 || a.desc.toLowerCase().indexOf(q) >= 0 || a.id.indexOf(q) >= 0) soft.push(a);
      });
      return hit.concat(soft);
    },
    count: function () { return Object.keys(apps).length; }
  };
})();
